<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import {
  getOrganisationArticles, getOrganisationContent, getOrganisationAdminArticles,
  createOrganisationArticle, updateOrganisationArticle, deleteOrganisationArticle,
  saveOrganisationContent,
  type OrganisationArticle, type OrganisationContent,
} from '@/services/organisation'

const categories = ['All', 'History', 'Organisation', 'Traditions', 'Chronicles', 'Archive']
const articles = ref<OrganisationArticle[]>([])
const content = ref<OrganisationContent>({})
const loading = ref(true)
const saving = ref(false)
const isAdmin = ref(false)
const pageError = ref('')
const pageNotice = ref('')
const searchQuery = ref('')
const selectedCategory = ref('All')
const dialogOpen = ref(false)
const pageEditorOpen = ref(false)
const editingId = ref<string | number | null>(null)
const articleToRead = ref<OrganisationArticle | null>(null)
const editorError = ref('')

const defaultContent: OrganisationContent = {
  hero_title: 'BUILT ON\nOUR HISTORY.', hero_subtitle: 'OUR STORY. OUR PEOPLE. OUR LEGACY.',
  hero_description: 'Explore the history, organisation, traditions and milestones that have shaped Devils Mercy MC.',
  hero_image: '/images/organisation/hero.jpg', intro_overline: 'DEVILS MERCY MOTORCYCLE CLUB',
  intro_title: 'MORE THAN\nA NAME.', intro_lead: 'Built through loyalty, shaped by the road, and defined by those who stand beside us.',
  intro_text: 'Devils Mercy MC is more than a name or a patch. It represents a shared identity, a commitment to the club, and a story that continues with every chapter we write together.\n\nFrom the people who laid the foundations to those who carry the club forward, every chapter becomes part of something greater than any one individual.',
  intro_signature: 'OUR CLUB. OUR BROTHERHOOD. OUR LEGACY.', archive_overline: 'DOCUMENTED. PRESERVED. REMEMBERED.',
  archive_title: 'THE ARCHIVE.', archive_text: 'Every club has a story. Here, ours is preserved. Explore our history, our organisation and the milestones that continue to shape our identity.',
  statement_title: 'THE ROAD\nCONTINUES.', statement_text: 'Our past defines where we came from. Our brotherhood determines where we go next.',
  statement_final: 'THE STORY IS NEVER FINISHED.', statement_image: '/images/organisation/statement.jpg',
}
const pageForm = ref<OrganisationContent>({ ...defaultContent })
const emptyArticle = (): OrganisationArticle => ({ title: '', category: 'History', excerpt: '', content: '', image: '', date: new Date().toISOString().slice(0, 10), featured: false, published: true })
const form = ref<OrganisationArticle>(emptyArticle())

const filteredArticles = computed(() => {
  const q = searchQuery.value.trim().toLowerCase()
  return articles.value.filter(a => (selectedCategory.value === 'All' || a.category === selectedCategory.value) && (!q || [a.title,a.excerpt,a.content,a.category].some(v => String(v || '').toLowerCase().includes(q)))).sort((a,b) => String(b.date || '').localeCompare(String(a.date || '')))
})
const featuredArticles = computed(() => filteredArticles.value.filter(a => a.featured))
const regularArticles = computed(() => filteredArticles.value.filter(a => !a.featured))
const pageText = (key: string) => content.value[key] || defaultContent[key] || ''

async function load() {
  loading.value = true; pageError.value = ''
  try {
    const [publicArticles, pageContent] = await Promise.all([getOrganisationArticles(), getOrganisationContent()])
    articles.value = publicArticles
    content.value = { ...defaultContent, ...pageContent }
    pageForm.value = { ...defaultContent, ...pageContent }
    // Only users granted the website.manage permission can load the complete admin list.
    try { articles.value = await getOrganisationAdminArticles(); isAdmin.value = true } catch { isAdmin.value = false }
  } catch (e) { pageError.value = errorMessage(e); }
  finally { loading.value = false }
}
function errorMessage(e: unknown) { return e instanceof Error ? e.message : 'Ett oväntat fel uppstod.' }
function openArticle(article: OrganisationArticle) { articleToRead.value = article }
function startNew() { editingId.value = null; form.value = emptyArticle(); editorError.value = ''; dialogOpen.value = true }
function startEdit(article: OrganisationArticle) { editingId.value = article.id ?? null; form.value = { ...emptyArticle(), ...article }; articleToRead.value = null; editorError.value = ''; dialogOpen.value = true }
async function saveArticle() {
  editorError.value = ''; pageNotice.value = ''
  if (!isAdmin.value) { editorError.value = 'Du saknar behörighet att ändra artiklar.'; return }
  if (!form.value.title.trim() || !form.value.excerpt.trim() || !form.value.content.trim()) { editorError.value = 'Titel, kort beskrivning och artikeltext måste fyllas i.'; return }
  saving.value = true
  try {
    const payload = { ...form.value, title: form.value.title.trim(), excerpt: form.value.excerpt.trim(), content: form.value.content.trim(), image: form.value.image.trim(), published: form.value.published ?? true }
    if (editingId.value !== null) await updateOrganisationArticle(editingId.value, payload)
    else await createOrganisationArticle(payload)
    dialogOpen.value = false; pageNotice.value = 'Artikeln har sparats i databasen.'; await load()
  } catch (e) { editorError.value = errorMessage(e) } finally { saving.value = false }
}
async function deleteArticle(article: OrganisationArticle) {
  if (!isAdmin.value || article.id == null) return
  if (!window.confirm(`Vill du verkligen ta bort "${article.title}" från databasen?`)) return
  pageError.value = ''
  try { await deleteOrganisationArticle(article.id); if (articleToRead.value?.id === article.id) articleToRead.value = null; pageNotice.value = 'Artikeln har tagits bort.'; await load() }
  catch (e) { pageError.value = errorMessage(e) }
}
function openPageEditor() { pageForm.value = { ...defaultContent, ...content.value }; pageEditorOpen.value = true }
async function savePageContent() {
  if (!isAdmin.value) return
  saving.value = true; pageError.value = ''; pageNotice.value = ''
  try { await saveOrganisationContent(pageForm.value); content.value = { ...pageForm.value }; pageEditorOpen.value = false; pageNotice.value = 'Organisation-sidans texter och bildsökvägar har sparats i databasen.' }
  catch (e) { pageError.value = errorMessage(e) } finally { saving.value = false }
}
function formatDate(date?: string) { if (!date) return ''; const d = new Date(`${date.slice(0,10)}T12:00:00`); return Number.isNaN(d.getTime()) ? date : new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric'}).format(d) }
const pageFields = [
 { key:'hero_title', label:'HERO TITLE (use a new line to split)', multiline:true }, { key:'hero_subtitle', label:'HERO SUBTITLE', multiline:false }, { key:'hero_description', label:'HERO DESCRIPTION', multiline:true }, { key:'hero_image', label:'HERO IMAGE PATH / URL', multiline:false },
 { key:'intro_overline', label:'INTRO OVERLINE', multiline:false }, { key:'intro_title', label:'INTRO TITLE (use a new line to split)', multiline:true }, { key:'intro_lead', label:'INTRO LEAD', multiline:true }, { key:'intro_text', label:'INTRO TEXT (separate paragraphs with a blank line)', multiline:true }, { key:'intro_signature', label:'INTRO SIGNATURE', multiline:false },
 { key:'archive_overline', label:'ARCHIVE OVERLINE', multiline:false }, { key:'archive_title', label:'ARCHIVE TITLE', multiline:false }, { key:'archive_text', label:'ARCHIVE DESCRIPTION', multiline:true }, { key:'statement_title', label:'STATEMENT TITLE (use a new line to split)', multiline:true }, { key:'statement_text', label:'STATEMENT TEXT', multiline:true }, { key:'statement_final', label:'STATEMENT FINAL LINE', multiline:false }, { key:'statement_image', label:'STATEMENT IMAGE PATH / URL', multiline:false },
]

onMounted(load)
</script>

<template>
  <div class="site-shell org-page">
    <main>
      <section class="hero org-hero" :style="{ '--org-hero-image': `url('${pageText('hero_image')}')` }">
        <div class="hero-image org-hero-image" role="img" aria-label="Devils Mercy Motorcycle Club" /><div class="hero-overlay" />
        <div class="hero-content">
          <p class="eyebrow"><span class="eyebrow-line" /> DEVILS MERCY MC <span class="eyebrow-dot" /> OUR ORGANIZATION</p>
          <h1 class="org-hero-title">{{ pageText('hero_title').split('\n')[0] }}<br><span>{{ pageText('hero_title').split('\n').slice(1).join(' ') }}</span></h1>
          <div class="hero-divider"><span /></div><p class="hero-tagline">{{ pageText('hero_subtitle') }}</p><p class="hero-description">{{ pageText('hero_description') }}</p>
          <div class="hero-actions"><a href="#organisation-archive" class="button-primary">EXPLORE THE ARCHIVE <v-icon icon="mdi-arrow-down" size="18" /></a><RouterLink to="/charters" class="button-secondary">OUR CHARTERS <v-icon icon="mdi-arrow-top-right" size="17" /></RouterLink></div>
        </div>
        <div class="hero-bottom"><span class="hero-location">DEVILS MERCY MOTORCYCLE CLUB</span><span class="hero-scroll">SCROLL TO DISCOVER <v-icon icon="mdi-arrow-down" size="15" /></span></div>
      </section>

      <section class="section-padding org-intro"><div class="section-label"><span class="section-label-number">01</span><span class="section-label-line" /><span>WHO WE ARE</span></div>
        <div class="intro-grid org-intro-grid"><div class="org-intro-heading-wrap"><p class="org-overline">{{ pageText('intro_overline') }}</p><h2 class="intro-heading org-intro-heading">{{ pageText('intro_title').split('\n')[0] }}<br><span>{{ pageText('intro_title').split('\n').slice(1).join(' ') }}</span></h2><div class="org-heading-accent"><span class="org-heading-accent-line" /><span>LOYALTY · BROTHERHOOD · RESPECT</span></div></div>
          <div class="intro-copy org-intro-copy"><p class="org-lead">{{ pageText('intro_lead') }}</p><p v-for="(paragraph, i) in pageText('intro_text').split('\n\n')" :key="i">{{ paragraph }}</p><p class="org-signature">{{ pageText('intro_signature') }}</p><a href="#organisation-archive" class="text-link">EXPLORE OUR STORY <v-icon icon="mdi-arrow-down-right" size="18" /></a></div></div>
      </section>

      <section id="organisation-archive" class="section-padding org-archive"><div class="section-label"><span class="section-label-number">02</span><span class="section-label-line" /><span>THE HISTORY &amp; LEGACY</span></div>
        <div class="section-heading-row org-heading-row"><div><p class="org-overline">{{ pageText('archive_overline') }}</p><h2 class="section-title">{{ pageText('archive_title').split(' ')[0] }} <span>{{ pageText('archive_title').split(' ').slice(1).join(' ') }}</span></h2><p class="org-archive-intro">{{ pageText('archive_text') }}</p></div>
          <div class="org-admin-actions" v-if="isAdmin"><button class="org-outline-button" type="button" @click="openPageEditor"><v-icon icon="mdi-text-box-edit-outline" size="17" /> EDIT PAGE</button><button class="button-primary org-add-button" type="button" @click="startNew"><v-icon icon="mdi-plus" size="18" /> ADD ARTICLE</button></div>
        </div>
        <p v-if="pageError" class="org-alert org-alert-error">{{ pageError }}</p><p v-if="pageNotice" class="org-alert">{{ pageNotice }}</p><p v-if="loading" class="org-loading">Loading organisation archive…</p>
        <div class="org-toolbar"><div class="org-search"><v-icon icon="mdi-magnify" size="20" /><input v-model="searchQuery" type="search" placeholder="Search the archive..." aria-label="Search articles" /><button v-if="searchQuery" class="org-clear-search" type="button" aria-label="Clear search" @click="searchQuery = ''"><v-icon icon="mdi-close" size="17" /></button></div><div class="org-result-count"><span>{{ String(filteredArticles.length).padStart(2,'0') }}</span> ARTICLES FOUND</div></div>
        <div class="org-category-list"><button v-for="category in categories" :key="category" type="button" class="org-category" :class="{'org-category-active': selectedCategory === category}" @click="selectedCategory = category">{{ category }}</button></div>
        <div v-if="featuredArticles.length" class="destination-grid org-featured-grid"><article v-for="article in featuredArticles" :key="article.id" class="destination-card org-article-card"><button class="org-card-open" type="button" :aria-label="`Read ${article.title}`" @click="openArticle(article)"><div class="destination-image org-card-image"><img v-if="article.image" :src="article.image" :alt="article.title" loading="lazy" @error="($event.target as HTMLImageElement).style.display='none'"><span class="org-image-number">{{ article.category.toUpperCase() }}</span><span class="org-image-arrow"><v-icon icon="mdi-arrow-top-right" size="21" /></span></div><div class="destination-content"><div class="org-card-meta"><span>{{ article.category }}</span><span>{{ formatDate(article.date) }}</span></div><h3>{{ article.title }}</h3><p>{{ article.excerpt }}</p><span class="org-read-link">READ ARTICLE <v-icon icon="mdi-arrow-right" size="17" /></span></div></button><div v-if="isAdmin" class="org-card-admin"><button type="button" @click="startEdit(article)"><v-icon icon="mdi-pencil-outline" size="16" /> EDIT</button><button type="button" class="org-delete-action" @click="deleteArticle(article)"><v-icon icon="mdi-trash-can-outline" size="16" /> DELETE</button></div></article></div>
        <div v-if="regularArticles.length" class="org-list"><article v-for="(article,index) in regularArticles" :key="article.id" class="org-list-item"><div class="org-list-number">{{ String(index+1+featuredArticles.length).padStart(2,'0') }}</div><button type="button" class="org-list-main" @click="openArticle(article)"><span class="org-list-category">{{ article.category }}</span><span class="org-list-title">{{ article.title }}</span><span class="org-list-excerpt">{{ article.excerpt }}</span></button><span class="org-list-date">{{ formatDate(article.date) }}</span><div v-if="isAdmin" class="org-list-actions"><button type="button" aria-label="Edit article" @click="startEdit(article)"><v-icon icon="mdi-pencil-outline" size="18" /></button><button type="button" aria-label="Delete article" class="org-delete-action" @click="deleteArticle(article)"><v-icon icon="mdi-trash-can-outline" size="18" /></button><button type="button" aria-label="Read article" @click="openArticle(article)"><v-icon icon="mdi-arrow-top-right" size="20" /></button></div></article></div>
        <div v-if="!loading && !filteredArticles.length" class="org-empty-state"><v-icon icon="mdi-text-box-search-outline" size="42" /><h3>NO ARTICLES FOUND</h3><p>Try another search or choose a different category.</p><button type="button" class="org-outline-button" @click="searchQuery=''; selectedCategory='All'">CLEAR FILTERS</button></div>
      </section>
      <section class="club-statement org-statement" :style="{ '--org-statement-image': `url('${pageText('statement_image')}')` }"><div class="statement-image org-statement-image" /><div class="statement-overlay" /><div class="statement-content"><p class="eyebrow"><span class="eyebrow-line" /> DEVILS MERCY MC</p><h2>{{ pageText('statement_title').split('\n')[0] }}<br><span>{{ pageText('statement_title').split('\n').slice(1).join(' ') }}</span></h2><p>{{ pageText('statement_text') }}</p><p class="org-final-line">{{ pageText('statement_final') }}</p><RouterLink to="/charters" class="button-primary">DISCOVER OUR CHARTERS <v-icon icon="mdi-arrow-top-right" size="18" /></RouterLink></div></section>
    </main>

    <Transition name="org-modal"><div v-if="articleToRead" class="org-modal-backdrop" @click.self="articleToRead=null"><section class="org-reader" role="dialog" aria-modal="true" :aria-label="articleToRead.title"><div class="org-reader-top"><span class="org-reader-label">DEVILS MERCY MC / {{ articleToRead.category.toUpperCase() }}</span><button type="button" class="org-modal-close" aria-label="Close article" @click="articleToRead=null"><v-icon icon="mdi-close" size="22" /></button></div><div v-if="articleToRead.image" class="org-reader-image"><img :src="articleToRead.image" :alt="articleToRead.title" @error="($event.target as HTMLImageElement).style.display='none'"></div><div class="org-reader-body"><div class="org-card-meta"><span>{{ articleToRead.category }}</span><span>{{ formatDate(articleToRead.date) }}</span></div><h2>{{ articleToRead.title }}</h2><p class="org-reader-excerpt">{{ articleToRead.excerpt }}</p><div class="org-reader-content">{{ articleToRead.content }}</div><div class="org-reader-actions"><button v-if="isAdmin" type="button" class="button-primary" @click="startEdit(articleToRead!)"><v-icon icon="mdi-pencil-outline" size="17" /> EDIT ARTICLE</button><button type="button" class="org-outline-button" @click="articleToRead=null">CLOSE</button></div></div></section></div></Transition>

    <Transition name="org-modal"><div v-if="dialogOpen" class="org-modal-backdrop" @click.self="dialogOpen=false"><section class="org-editor" role="dialog" aria-modal="true" aria-label="Article editor"><div class="org-editor-header"><div><p class="org-overline">DEVILS MERCY MC / SQL CONTENT</p><h2>{{ editingId !== null ? 'EDIT ARTICLE' : 'NEW ARTICLE' }}</h2></div><button type="button" class="org-modal-close" aria-label="Close editor" @click="dialogOpen=false"><v-icon icon="mdi-close" size="22" /></button></div><form class="org-editor-form" @submit.prevent="saveArticle"><label><span>ARTICLE TITLE</span><input v-model="form.title" type="text" maxlength="220" required></label><div class="org-editor-row"><label><span>CATEGORY</span><select v-model="form.category" required><option v-for="category in categories.filter(c=>c!=='All')" :key="category" :value="category">{{ category }}</option></select></label><label><span>DATE</span><input v-model="form.date" type="date" required></label></div><label><span>IMAGE PATH OR URL</span><input v-model="form.image" type="text" placeholder="/images/organisation/history.jpg"></label><label><span>SHORT DESCRIPTION</span><textarea v-model="form.excerpt" rows="3" maxlength="300" required /></label><label><span>ARTICLE CONTENT</span><textarea v-model="form.content" rows="8" required /></label><label class="org-featured-toggle"><input v-model="form.featured" type="checkbox"><span>FEATURE THIS ARTICLE</span></label><label class="org-featured-toggle"><input v-model="form.published" type="checkbox"><span>PUBLISHED ON PUBLIC PAGE</span></label><p v-if="editorError" class="org-editor-error"><v-icon icon="mdi-alert-circle-outline" size="18" />{{ editorError }}</p><div class="org-editor-actions"><button type="button" class="org-outline-button" @click="dialogOpen=false">CANCEL</button><button type="submit" class="button-primary" :disabled="saving"><v-icon icon="mdi-content-save-outline" size="18" />{{ saving ? 'SAVING…' : 'SAVE ARTICLE' }}</button></div></form></section></div></Transition>

    <Transition name="org-modal"><div v-if="pageEditorOpen" class="org-modal-backdrop" @click.self="pageEditorOpen=false"><section class="org-editor org-page-editor" role="dialog" aria-modal="true" aria-label="Edit organisation page"><div class="org-editor-header"><div><p class="org-overline">DEVILS MERCY MC / SQL CONTENT</p><h2>EDIT ORGANISATION PAGE</h2></div><button type="button" class="org-modal-close" @click="pageEditorOpen=false"><v-icon icon="mdi-close" size="22" /></button></div><form class="org-editor-form" @submit.prevent="savePageContent"><p class="org-page-editor-help">Dessa fält sparas i SQL och visas på sidan. Bildfälten tar en sökväg i public-mappen eller en bild-URL.</p><label v-for="field in pageFields" :key="field.key"><span>{{ field.label }}</span><textarea v-if="field.multiline" v-model="pageForm[field.key]" rows="3" /><input v-else v-model="pageForm[field.key]" type="text"></label><p v-if="pageError" class="org-editor-error">{{ pageError }}</p><div class="org-editor-actions"><button type="button" class="org-outline-button" @click="pageEditorOpen=false">CANCEL</button><button type="submit" class="button-primary" :disabled="saving"><v-icon icon="mdi-content-save-outline" size="18" />{{ saving ? 'SAVING…' : 'SAVE PAGE' }}</button></div></form></section></div></Transition>
  </div>
</template>


<style scoped>
